-- Venue Live Guest "Ucapan Lebaran di Kampung". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara lebaran), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'lebaran', 'Ucapan Lebaran di Kampung', 'lebaran', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 142, 'center 38%',
  $t${"name":"Lebaran di Kampung","orn":"diamond","ui":{"ivory":"#F7F3E2","white":"#FFFFFF","soft":"#E3EBC8","soft2":"#8FB070","accent":"#2F6B3A","deep":"#1C4527","ink":"#1F3523","mute":"#6A7F62","line":"#D9E2BE","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#F7F1DA","ink":"#1F3523","accent":"#2F6B3A","gold":"#D9A21B","leaf":"#E3EBC8","hbg":"rgba(247,243,226,.94)","hline":"#D9A21B","motif":"diamond"},"hud":{"bg":"rgba(28,69,39,.9)","acc":"#F2C94C","on":"#1F3523"},"scr":{"wine":"#1C4527","veil":"247,243,226"}}$t$::jsonb
